<?php
declare(strict_types=1);
require_once __DIR__.'/Support/ReviewedLocalFixture.php';
use DigiForge\Portal\ReviewedAcceptanceContract as Contract;
use DigiForge\Portal\ReviewedScopedPolicy as Policy;
use DigiForge\Portal\AcceptanceEvidenceResolver as Resolver;
final class AcceptanceResolverIntegrationTest extends WP_UnitTestCase {
 private array $actors;
 private string $key='sandbox:WORKFLOW:research:research';
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();$this->actors=ReviewedLocalFixture::actors('digital');(new DigiForge\REST\ReviewedContractsController())->register();(new DigiForge\Security\ShopAccessRestGuard())->register();do_action('rest_api_init');}
 private function policy(int $expiry=0):array {$p=Policy::propose('digital',['environment'=>'sandbox','scope'=>'WORKFLOW','workflow'=>'research','capability'=>'research','enabled'=>false],time()-1,$expiry?:time()+3600,wp_generate_uuid4(),0);self::assertNotWPError($p);wp_set_current_user($this->actors['reviewer']);$r=Policy::decide('digital',$this->key,$p['revision'],$p['proposal_hash'],'APPROVED',wp_generate_uuid4());self::assertNotWPError($r);wp_set_current_user($this->actors['author']);return $r;}
 private function contract(array $ref,?array $formula=null):void {$input=['version'=>1,'criterion'=>'BP-portal-17-conversion','scope'=>'integration-fixture','workflow'=>'research','definition'=>['numerator'=>'Synthetic','denominator'=>'Synthetic','population'=>'Synthetic','attribution'=>'Synthetic shop-scoped source','period_start'=>'2026-01-01T00:00:00Z','period_end'=>'2026-02-01T00:00:00Z','source_records'=>[$ref],'formula_ref'=>$formula]];$p=Contract::propose('digital',$input,time()-1,time()+3600,wp_generate_uuid4(),0);self::assertNotWPError($p);wp_set_current_user($this->actors['reviewer']);self::assertNotWPError(Contract::decide('digital',$input['criterion'],$input['scope'],$p['revision'],$p['proposal_hash'],'APPROVED',wp_generate_uuid4()));wp_set_current_user($this->actors['author']);}
 private function read(array $extra=['environment'=>'sandbox'],string $shop='digital'):WP_REST_Response {$r=new WP_REST_Request('GET','/digiforge/v1/reviewed-contracts/'.$shop.'/acceptance');$r->set_query_params(array_replace(['criterion'=>'BP-portal-17-conversion','scope'=>'integration-fixture'],$extra));return rest_get_server()->dispatch($r);}
 public function testReadComposesResolutionWithoutPromotingCertification():void {$this->policy();$ref=Resolver::policyReference('digital',$this->key);self::assertNotWPError($ref);$this->contract($ref);$r=$this->read();self::assertSame(200,$r->get_status());$d=$r->get_data();self::assertArrayHasKey('evidence_resolution',$d);self::assertSame('CURRENT_REVIEW',$d['status']);self::assertSame('APPROVED',$d['review_status']);self::assertSame('MATCHED_LOCAL_RECORDS',$d['evidence_resolution']['resolution_state']);self::assertSame(1,$d['evidence_resolution']['matched_record_count']);self::assertFalse($d['evidence_resolution']['references'][0]['purpose_verified']);self::assertSame('UNVERIFIED',$d['evidence_state']);self::assertSame('UNKNOWN',$d['value_state']);self::assertFalse($d['external_execution_authorized']);self::assertFalse($d['supplier_approved']);self::assertTrue(DigiForge\Core\Settings::safety_locked());}
 public function testOldRequestsRemainReadOnlyWithoutInferringEnvironment():void {$this->policy();$this->contract(Resolver::policyReference('digital',$this->key));$r=$this->read([]);self::assertSame(200,$r->get_status());self::assertSame('UNKNOWN',$r->get_data()['evidence_resolution']['resolution_state']);self::assertSame('UNKNOWN',$r->get_data()['evidence_resolution']['environment']);self::assertSame(0,$r->get_data()['evidence_resolution']['matched_record_count']);}
 public function testForeignDeferredAnonymousAndMalformedEnvironmentsDeny():void {foreach(['personalized_pod','standard_pod','jewelry']as $shop)self::assertSame(403,$this->read(['environment'=>'sandbox'],$shop)->get_status());foreach(['staging','',null,[],123]as $env)self::assertSame(400,$this->read(['environment'=>$env])->get_status());self::assertSame(400,$this->read(['environment'=>'sandbox','shop'=>'jewelry'])->get_status());wp_set_current_user(0);self::assertSame(401,$this->read()->get_status());}
 public function testMismatchedEnvironmentNeverBorrowsApprovedReview():void {$this->policy();$this->contract(Resolver::policyReference('digital',$this->key));$d=$this->read(['environment'=>'production'])->get_data();self::assertSame('CURRENT_REVIEW',$d['status']);self::assertSame('UNKNOWN',$d['evidence_resolution']['resolution_state']);self::assertSame(0,$d['evidence_resolution']['matched_record_count']);}
 public function testSourceRevocationIsVisibleWithoutInvalidatingParentHistory():void {$p=$this->policy();$this->contract(Resolver::policyReference('digital',$this->key));self::assertSame('MATCHED_LOCAL_RECORDS',$this->read()->get_data()['evidence_resolution']['resolution_state']);wp_set_current_user($this->actors['reviewer']);self::assertNotWPError(Policy::decide('digital',$this->key,$p['revision'],$p['proposal_hash'],'REVOKED',wp_generate_uuid4()));wp_set_current_user($this->actors['author']);$d=$this->read()->get_data();self::assertSame('CURRENT_REVIEW',$d['status']);self::assertSame('UNKNOWN',$d['evidence_resolution']['resolution_state']);}
 public function testSourceExpiryFailsClosedWhileParentRemainsReviewed():void {$p=$this->policy(time()+2);$this->contract(Resolver::policyReference('digital',$this->key));while(time()<$p['expires_at'])usleep(50000);$d=$this->read()->get_data();self::assertSame('CURRENT_REVIEW',$d['status']);self::assertSame('UNKNOWN',$d['evidence_resolution']['resolution_state']);}
 /** @dataProvider failures */
 public function testUnresolvedSourcesRemainUnverifiedInRealRestDispatch(string $failure):void {$this->policy();$ref=Resolver::policyReference('digital',$this->key);if($failure==='hash')$ref['sha256']=str_repeat('0',64);elseif($failure==='version')$ref['reference']=str_replace('/1/2','/2/2',$ref['reference']);else $ref['reference']='local://opaque/unsupported';$this->contract($ref);$d=$this->read()->get_data();self::assertSame('UNKNOWN',$d['evidence_resolution']['resolution_state']);self::assertSame('UNVERIFIED',$d['evidence_state']);self::assertSame(0,$d['evidence_resolution']['matched_record_count']);}
 public static function failures():array{return [['hash'],['version'],['unsupported']];}
 public function testDuplicateReferencesAreDisplayedOnce():void {$this->policy();$ref=Resolver::policyReference('digital',$this->key);$this->contract($ref,$ref);$d=$this->read()->get_data()['evidence_resolution'];self::assertSame(1,$d['matched_record_count']);self::assertCount(1,$d['references']);self::assertSame(2,$d['references'][0]['occurrences']);}
 public function testParentRevocationDuringResolutionRejectsMixedSnapshot():void {
  $this->policy();$this->contract(Resolver::policyReference('digital',$this->key));$parent=Contract::current('digital','BP-portal-17-conversion','integration-fixture');self::assertNotWPError($parent);
  $option='digiforge_local_review_'.hash('sha256',DigiForge\Orders\Validator::canonicalJson(['policy','digital',$this->key]));$changed=null;$actors=$this->actors;$intercept=null;
  $intercept=static function(string $sql)use(&$intercept,$option,&$changed,$actors,$parent):string {
   if(str_starts_with(ltrim($sql),'SELECT option_value')&&str_contains($sql,$option)){
    remove_filter('query',$intercept);wp_set_current_user($actors['reviewer']);$changed=Contract::decide('digital','BP-portal-17-conversion','integration-fixture',$parent['revision'],$parent['proposal_hash'],'REVOKED',wp_generate_uuid4());wp_set_current_user($actors['author']);
   }return $sql;
  };add_filter('query',$intercept);
  try{$r=$this->read();self::assertNotNull($changed);self::assertNotWPError($changed);self::assertSame(409,$r->get_status());self::assertArrayNotHasKey('evidence_resolution',$r->get_data());}finally{remove_filter('query',$intercept);wp_set_current_user($actors['author']);}
 }
 public function testConflictingReferencesNeverDisplayMatchingEvidence():void {$this->policy();$ref=Resolver::policyReference('digital',$this->key);$bad=$ref;$bad['sha256']=str_repeat('0',64);$this->contract($ref,$bad);$d=$this->read()->get_data()['evidence_resolution'];self::assertSame('UNKNOWN',$d['resolution_state']);self::assertSame(0,$d['matched_record_count']);self::assertSame('CONFLICTING_REFERENCE',$d['references'][0]['reason']);}
}
